const fs = require('fs'), path = require('path');
const { chromium } = require('D:/repository/苏住房G/node_modules/playwright');
const TEMP = process.env.TEMP || 'C:/Users/Administrator/AppData/Local/Temp';
const DIR = path.join(TEMP, 'zentao-6915');
const BASE = 'http://localhost:8165';
(async () => {
  const browser = await chromium.launch({ headless: true });
  const ctx = await browser.newContext({ viewport: { width: 1920, height: 1080 } });
  const page = await ctx.newPage();
  const out = [];
  for (let i = 1; i <= 6; i++) {
    const codeP = page.waitForResponse(r => r.url().includes('/code'), { timeout: 20000 });
    await page.goto(BASE, { waitUntil: 'domcontentloaded' }).catch(() => {});
    let body = null;
    try { body = await (await codeP).json(); } catch (e) {}
    if (!body || !body.data) { console.log('NO_CODE', i); continue; }
    const img = path.join(DIR, `v-${i}.jpg`);
    fs.writeFileSync(img, Buffer.from(String(body.data).replace(/^data:image\/\w+;base64,/, ''), 'base64'));
    out.push({ i, uuid: body.uuid, img });
    console.log('CODE', i, body.uuid, img);
    await page.waitForTimeout(300);
  }
  fs.writeFileSync(path.join(DIR, 'codes.json'), JSON.stringify(out, null, 2));
  console.log('DONE', out.length);
  await browser.close();
})().catch(e => { console.error('FATAL', e); process.exit(1); });

const fs = require('fs'), path = require('path');
const { chromium } = require('D:/repository/苏住房G/node_modules/playwright');
const TEMP = process.env.TEMP || 'C:/Users/Administrator/AppData/Local/Temp';
const DIR = path.join(TEMP, 'zentao-6915');
const BASE = 'http://localhost:8165';
(async () => {
  const browser = await chromium.launch({ headless: true });
  const ctx = await browser.newContext({
    viewport: { width: 1920, height: 1080 },
    storageState: path.join(DIR, 'state.json'),
  });
  const page = await ctx.newPage();
  await page.goto(BASE + '/#/safety/flood/floodScreen', { waitUntil: 'domcontentloaded' }).catch(() => {});
  await page.waitForTimeout(6000);
  console.log('URL', page.url());
  console.log('TITLE', await page.title());
  console.log('HM_CHART_COUNT', await page.locator('.hm-chart canvas').count());
  console.log('HEATMAP_WRAP', await page.locator('.heatmap-wrap').count());
  console.log('BODY_TEXT_HEAD', (await page.locator('body').innerText().catch(() => '')).slice(0, 500).replace(/\n/g, ' | '));
  // 尝试多点悬停于热力图 canvas
  const box = await page.locator('.hm-chart canvas').first().boundingBox().catch(() => null);
  console.log('CANVAS_BOX', JSON.stringify(box));
  if (box) {
    const pts = [
      [0.5, 0.5], [0.35, 0.45], [0.6, 0.55], [0.45, 0.6], [0.7, 0.4], [0.3, 0.6], [0.55, 0.35],
    ];
    for (const [fx, fy] of pts) {
      await page.mouse.move(box.x + box.width * fx, box.y + box.height * fy, { steps: 5 });
      await page.waitForTimeout(700);
    }
    // 停在中心并等 5s+ 观察是否出现详情卡
    await page.mouse.move(box.x + box.width * 0.5, box.y + box.height * 0.5, { steps: 5 });
  }
  await page.waitForTimeout(5500);
  // 检查是否存在详情卡特征文本（原 hoverItem 卡片）
  const body = await page.locator('body').innerText().catch(() => '');
  const cardHits = ['暂无检查事项', '物业管理区域', '检查事项', '所属区域', '隐患数量'].filter(k => body.includes(k));
  console.log('CARD_TEXT_HITS', JSON.stringify(cardHits));
  const ts = new Date().toISOString().replace(/[-:T]/g, '').slice(0, 15);
  const shot = path.join(DIR, `verify-hover-${ts}.png`);
  await page.screenshot({ path: shot, fullPage: true }).catch(e => console.log('SHOT_FAIL', e.message));
  console.log('SHOT', shot);
  await browser.close();
})().catch(e => { console.error('FATAL', e); process.exit(1); });

